/*
 * A295058  Solution of the complementary equation a(n) = 2*a(n-1) - b(n-1),
 *          where a(0) = 3, a(1) = 5, b(0) = 1, and (a(n)) and (b(n)) are
 *          increasing complementary sequences.
 * https://oeis.org/A295058
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 16, u32 n <= 30, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Helpers:   grow_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Complementary sequences a(n) and b(n) are generated by scanning for
 * the smallest positive integer not yet present in the union of the
 * previously computed a() and b() values.  a(0)=3, a(1)=5,
 * b(0)=1 and for n>=1:
 *     a(n) = 2*a(n-1) - b(n-1)
 *
 * The implementation memoises the sequences in static arrays and
 * maintains two indices that allow each missing number to be found in
 * O(1) amortised time per term.  This yields an overall O(n) algorithm
 * for computing a(n).  */

/* required utilities */
#include <stddef.h>
#include <stdbool.h>
#include "../utils/grow_seq.h"

/* static tables holding the sequences */
static seq_t *A = NULL;
static seq_t *B = NULL;
static size_t A_cap = 0;
static size_t B_cap = 0;
static size_t A_len = 0;          /* number of a terms stored      */
static size_t B_len = 0;          /* number of b terms stored      */

/* indices used for the two‑pointer search for the next missing number */
static size_t ia = 0;             /* index into A (next possible match) */
static size_t ib = 0;             /* index into B (next possible match) */

/* current candidate for a missing number */
static seq_t cur_candidate = 1;

/* initialise the tables with the seed values */
static void init_sequence(void)
{
    if (A_len == 0) {
        grow_seq(&A, &A_cap, 2);
        A[0] = (seq_t)3;
        A[1] = (seq_t)5;
        A_len = 2;
    }
    if (B_len == 0) {
        grow_seq(&B, &B_cap, 1);
        B[0] = (seq_t)1;
        B_len = 1;
    }
    /* indices are already 0; cur_candidate is 1 */
}

/* find the next missing integer not in A or B (using the two‑pointer method) */
static seq_t next_missing(void)
{
    while (1) {
        /* advance pointers past values strictly smaller than cur_candidate */
        while (ia < A_len && A[ia] < cur_candidate) ++ia;
        while (ib < B_len && B[ib] < cur_candidate) ++ib;

        /* check whether cur_candidate is already present */
        if ((ia < A_len && A[ia] == cur_candidate) ||
            (ib < B_len && B[ib] == cur_candidate)) {
            ++cur_candidate;
        } else {
            /* cur_candidate is missing */
            seq_t miss = cur_candidate;
            cur_candidate = miss + (seq_t)1;
            return miss;
        }
    }
}

/* grow the a and b tables up to index n (inclusive) */
static void ensure_a_upto(idx_t n)
{
    init_sequence();

    while (A_len <= (size_t)n) {
        /* generate the next b value (index B_len = A_len-1) */
        seq_t b_val = next_missing();

        /* append b_val */
        grow_seq(&B, &B_cap, B_len + 1);
        B[B_len++] = b_val;

        /* compute the new a value using the recurrence */
        seq_t a_prev = A[A_len - 1];
        seq_t a_val  = (seq_t)2 * a_prev - b_val;

        grow_seq(&A, &A_cap, A_len + 1);
        A[A_len++] = a_val;
    }
}

/* public entry point required by the judge */
seq_t a(idx_t n)
{
    ensure_a_upto(n);
    return A[(size_t)n];
}
